import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    N, M, K = data[:3]
    A = data[3:]
    size = 1 << 20

    # Walsh transform of the frequency table gives, for every character s,
    # the difference between the numbers of entries with even and odd dot
    # product with s.
    freq = [0] * size
    for x in A:
        freq[x] += 1
    h = 1
    while h < size:
        for i in range(0, size, h << 1):
            for j in range(i, i + h):
                x, y = freq[j], freq[j + h]
                freq[j] = x + y
                freq[j + h] = x - y
        h <<= 1

    # Coefficient of z^0 modulo z^M-1 in
    # (1+z)^(N-c) (1-z)^c, calculated by the cyclic roots-of-unity filter.
    # A field extension is not needed for this filter: evaluate over the
    # complex numbers and round the integer count before reducing modulo MOD.
    # This numerical route is unsuitable for large counts, so use exact
    # polynomial arithmetic via a recurrence over all subset cardinalities.
    # (The recurrence below computes the requisite coefficient directly.)

    # For each distinct c, calculate the cyclic product with binary exponentiation.
    cache = {}
    def cyclic_power(a, e):
        r = [0] * M
        r[0] = 1
        while e:
            if e & 1:
                q = [0] * M
                for i, x in enumerate(r):
                    if x:
                        for j, y in enumerate(a):
                            if y:
                                q[(i + j) % M] = (q[(i + j) % M] + x * y) % MOD
                r = q
            e >>= 1
            if e:
                q = [0] * M
                for i, x in enumerate(a):
                    if x:
                        for j, y in enumerate(a):
                            if y:
                                q[(i + j) % M] = (q[(i + j) % M] + x * y) % MOD
                a = q
        return r

    def get_count(c):
        if c not in cache:
            plus = cyclic_power([1, 1] + [0] * (M - 2), N - c) if M > 1 else [2 % MOD]
            minus = cyclic_power([1, MOD - 1] + [0] * (M - 2), c) if M > 1 else [0]
            val = sum(plus[i] * minus[-i % M] for i in range(M)) % MOD
            cache[c] = val
        return cache[c]

    # Walsh inversion: sum_x f(x) count(x) = 1/2^20 sum_s F(s) C(s).
    ans = 0
    for s, delta in enumerate(freq):
        c = (N - delta) // 2
        ans += pow(s, K, MOD) * get_count(c)
        ans %= MOD
    ans = ans * pow(size, MOD - 2, MOD) % MOD
    print(ans)

if __name__ == '__main__':
    main()

