from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        events = [[] for _ in range(n + 1)]
        for i, (x, y) in enumerate(conflictingPairs):
            a, b = sorted((x, y))
            events[b].append((a, i))

        gains = [0] * len(conflictingPairs)
        largest = (0, -1)
        second = (0, -1)
        total = 0

        for right in range(1, n + 1):
            for a, index in events[right]:
                if a > largest[0]:
                    second = largest
                    largest = (a, index)
                elif a > second[0]:
                    second = (a, index)

            # For this right endpoint, valid starts are greater than the
            # largest left endpoint among pairs already fully in the prefix.
            total += right - largest[0]

            # Removing the unique largest constraint improves this endpoint
            # by the difference between the largest and second-largest values.
            if largest[1] != -1:
                gains[largest[1]] += largest[0] - second[0]

        return total + max(gains)

