import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n = next(it)
    m = next(it)
    q = next(it)

    edges = []
    for _ in range(m):
        a = next(it) - 1
        b = next(it) - 1
        c = next(it)
        edges.append((a, b, c))

    queries = []
    closed = [False] * m
    for _ in range(q):
        t = next(it)
        if t == 1:
            k = next(it) - 1
            closed[k] = True
            queries.append((1, k))
        else:
            x = next(it) - 1
            y = next(it) - 1
            queries.append((2, x, y))

    inf = 10**30
    dist = [[inf] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for k, (a, b, c) in enumerate(edges):
        if not closed[k]:
            dist[a][b] = dist[b][a] = c

    # APSP in the graph after all closures.
    for k in range(n):
        row_k = dist[k]
        for i in range(n):
            dik = dist[i][k]
            if dik == inf:
                continue
            row_i = dist[i]
            for j in range(n):
                candidate = dik + row_k[j]
                if candidate < row_i[j]:
                    row_i[j] = candidate

    answers = []
    for query in reversed(queries):
        if query[0] == 2:
            value = dist[query[1]][query[2]]
            answers.append(str(-1 if value == inf else value))
        else:
            a, b, c = edges[query[1]]
            # Snapshot old distances so each candidate uses the new road at most once.
            to_a = [dist[i][a] for i in range(n)]
            to_b = [dist[i][b] for i in range(n)]
            from_a = dist[a][:]
            from_b = dist[b][:]
            for i in range(n):
                row = dist[i]
                via_a = to_a[i] + c
                via_b = to_b[i] + c
                for j in range(n):
                    candidate = via_a + from_b[j]
                    if candidate < row[j]:
                        row[j] = candidate
                    candidate = via_b + from_a[j]
                    if candidate < row[j]:
                        row[j] = candidate

    print('\n'.join(reversed(answers)))

if __name__ == '__main__':
    solve()

