import sys
import math

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[0], data[1]
    processes = []
    pos = 2
    for _ in range(n):
        a, p, b, q = data[pos:pos + 4]
        pos += 4
        processes.append((a, p, b, q))

    def feasible(target):
        total_cost = 0
        for a, p, b, q in processes:
            # For a fixed x modulo b/gcd(a,b), the cost with the
            # minimum y decreases linearly as x advances by that period.
            g = math.gcd(a, b)
            period = b // g
            last = (target - 1) // a  # x values for which y must be positive
            best = ((target + a - 1) // a) * p  # use only type S

            for residue in range(min(period, last + 1)):
                hi = residue + ((last - residue) // period) * period
                for x in (residue, hi):
                    y = (target - a * x + b - 1) // b
                    cost = p * x + q * y
                    if cost < best:
                        best = cost
            total_cost += best
            if total_cost > budget:
                return False
        return True

    low, high = 0, budget * 100 + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)

if __name__ == '__main__':
    main()

