class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        mod = 10**9 + 7
        length = len(s)
        allowed = [False] * (length + 1)
        for count in range(1, length + 1):
            value = count
            steps = 0
            while value != 1:
                value = value.bit_count()
                steps += 1
