                remaining = length - i - 1
                for suffix_ones in range(remaining + 1):
                    total_ones = prefix_ones + suffix_ones
                    if total_ones > 0 and allowed[total_ones]:
                        answer += comb(remaining, suffix_ones)
                prefix_ones += 1
