    n = int(input())
    g = [input().strip() for _ in range(n)]
    inf = 10**9
    d = [[inf] * n for _ in range(n)]
    pq = []
    for i in range(n):
        d[i][i] = 0
        heapq.heappush(pq, (0, i, i))
        for j, c in enumerate(g[i]):
            if c != '-' and d[i][j] > 1:
                d[i][j] = 1
                heapq.heappush(pq, (1, i, j))
    incoming = [[[] for _ in range(26)] for _ in range(n)]
    outgoing = [[[] for _ in range(26)] for _ in range(n)]
    for a in range(n):
        for b, c in enumerate(g[a]):
            if c != '-':
                k = ord(c) - 97
                outgoing[a][k].append(b)
                incoming[b][k].append(a)

    unresolved = sum(row.count(inf) for row in d)
    max_known = 1 if unresolved < n * n else 0
    while pq:
        val, u, v = heapq.heappop(pq)
        if d[u][v] != val:
            continue
        nd = val + 2
        # If every state is already reachable within this bound, no transition
        # from this state can improve anything.
        if unresolved == 0 and max_known <= nd:
