import sys

def feasible(H, U, D, X):
    lo = max(0, H - D[0])
    hi = min(U[0], H)
    if lo > hi:
        return False
    for u, d in zip(U[1:], D[1:]):
        next_lo = max(0, H - d, lo - X)
        next_hi = min(u, H, hi + X)
        if next_lo > next_hi:
            return False
        lo, hi = next_lo, next_hi
    return True

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, x = data[:2]
    U, D = [], []
    p = 2
    for _ in range(n):
        U.append(data[p])
        D.append(data[p + 1])
        p += 2

    low = 0
    high = min(u + d for u, d in zip(U, D))
    while low < high:
        mid = (low + high + 1) // 2
        if feasible(mid, U, D, x):
            low = mid
        else:
            high = mid - 1

    print(sum(U) + sum(D) - n * low)

if __name__ == '__main__':
    solve()

