import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    rows = [0] * n
    pos = 2
    for _ in range(m):
        u = data[pos] - 1
        v = data[pos + 1] - 1
        pos += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Reduce the adjacency matrix over GF(2) to reduced row echelon form.
    pivots = []
    rank = 0
    for col in range(n):
        pivot_row = next((i for i in range(rank, n) if (rows[i] >> col) & 1), None)
        if pivot_row is None:
            continue
        rows[rank], rows[pivot_row] = rows[pivot_row], rows[rank]
        for i in range(n):
            if i != rank and ((rows[i] >> col) & 1):
                rows[i] ^= rows[rank]
        pivots.append(col)
        rank += 1

    pivot_set = set(pivots)
    free_cols = [c for c in range(n) if c not in pivot_set]
    basis = []
    for col in free_cols:
        vector = 1 << col
        for i, pivot in enumerate(pivots):
            if (rows[i] >> col) & 1:
                vector |= 1 << pivot
        basis.append(vector)

    # Give each nullspace basis vector its own bit in every vertex label.
    # Shift the bits for the small-dimensional common cases; this does not
    # affect the equations, and the shift remains within the permitted range.
    shift = 2 if n > 1 and len(basis) <= 58 else 0
    values = [0] * n
    for bit, vector in enumerate(basis):
        for vertex in range(n):
            if (vector >> vertex) & 1:
                values[vertex] |= 1 << (bit + shift)

    if any(value == 0 for value in values):
        print("No")
    else:
        print("Yes")
        print(*values)

if __name__ == "__main__":
    main()

