            v=grid[r][c]; best=1
            nr,nc=r+dr[d],c+dc[d]
            if 0<=nr<n and 0<=nc<m and grid[nr][nc]==expected(v):
                best=max(best,1+bent(nr,nc,d),1+straight(nr,nc,(d+1)%4))
