class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        unused = list(range(1, n + 1))
        ans = []
        prev_parity = None
        while unused:
            chosen = None
            for x in unused:
                p = x % 2
                if prev_parity is not None and p == prev_parity:
                    continue
                rem = [y for y in unused if y != x]
                length = len(rem)
                need = 1 - p
                c_need = sum(y % 2 == need for y in rem)
                c_other = length - c_need
                if c_need != (length + 1) // 2 or c_other != length // 2:
                    block = 0
                else:
                    block = factorial(c_need) * factorial(c_other)
                if k > block:
                    k -= block
                else:
                    chosen = x
                    break
            if chosen is None:
                return []
            ans.append(chosen)
            unused.remove(chosen)
            prev_parity = chosen % 2
        return ans

