class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2

        # The contribution of a mirrored pair is the sum of its two
        # powers of ten; a center digit contributes only once.
        powers = [1 % k] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k
        weights = []
        for j in range(m):
            other = n - 1 - j
            if j == other:
                weights.append(powers[j])
            else:
                weights.append((powers[j] + powers[other]) % k)

        # suffix[i] is a bitmask of residues obtainable with half-digits
        # i..m-1. The first digit is restricted to 1..9.
        suffix = [0] * (m + 1)
        suffix[m] = 1  # residue zero
        for i in range(m - 1, -1, -1):
            old = suffix[i + 1]
            mask = 0
            lo = 1 if i == 0 else 0
            w = weights[i]
            for r in range(k):
                if (old >> r) & 1:
                    for d in range(lo, 10):
                        mask |= 1 << ((r + d * w) % k)
            suffix[i] = mask

        # Greedily choose each half-digit as large as possible while the
        # remaining suffix can still make the total residue zero.
        digits = []
        current = 0
        for i, w in enumerate(weights):
            lo = 1 if i == 0 else 0
            for d in range(9, lo - 1, -1):
                need = (-current - d * w) % k
                if (suffix[i + 1] >> need) & 1:
                    digits.append(str(d))
                    current = (current + d * w) % k
                    break

        half = ''.join(digits)
        return half + (half[:-1][::-1] if n % 2 else half[::-1])

