import sys
from functools import cmp_to_key

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, k = data[0], data[1]
    functions = [tuple(data[i:i + 2]) for i in range(2, len(data), 2)]

    # In an optimal ordering, functions are applied from inner to outer
    # in nondecreasing order of (A - 1) / B.
    def compare(f, g):
        a, b = f
        c, d = g
        left = (a - 1) * d
        right = (c - 1) * b
        return (left > right) - (left < right)

    functions.sort(key=cmp_to_key(compare))
    dp = [None] * (k + 1)
    dp[0] = 1
    processed = 0
    for a, b in functions:
        processed += 1
        for chosen in range(min(k, processed), 0, -1):
            if dp[chosen - 1] is not None:
                value = a * dp[chosen - 1] + b
                if dp[chosen] is None or value > dp[chosen]:
                    dp[chosen] = value
    print(dp[k])

if __name__ == '__main__':
    main()

