import sys

data = list(map(int, sys.stdin.buffer.read().split()))
N, M, L = data[:3]
a = data[3:3 + N]
b = data[3 + N:3 + N + M]
c = data[3 + N + M:]
values = a + b + c
K = len(values)
full = (1 << K) - 1
initial_h1 = (1 << N) - 1
initial_h2 = ((1 << M) - 1) << N

@lru_cache(None)
def winning(h1, h2, turn):
    hand = h1 if turn == 0 else h2
    if hand == 0:
        return False
    table = full ^ (h1 | h2)

    cards = hand
    while cards:
        bit = cards & -cards
        cards -= bit
        x = bit.bit_length() - 1
        remaining = hand ^ bit

        # Playing x without taking a card.
        if turn == 0:
            if not winning(remaining, h2, 1):
                return True
        else:
            if not winning(h1, remaining, 0):
                return True

        # Or take any smaller card that was already on the table.
        candidates = table
        while candidates:
            ybit = candidates & -candidates
            candidates -= ybit
            y = ybit.bit_length() - 1
            if values[y] < values[x]:
                if turn == 0:
                    if not winning(remaining | ybit, h2, 1):
                        return True
                else:
                    if not winning(h1, remaining | ybit, 0):
                        return True
    return False

print("Takahashi" if winning(initial_h1, initial_h2, 0) else "Aoki")

