def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    graph = [[] for _ in range(n)]
    j = 1
    for _ in range(n - 1):
        u, v, w = data[j] - 1, data[j + 1] - 1, data[j + 2]
        j += 3
        graph[u].append((v, w))
        graph[v].append((u, w))

    parent = [-1] * n
    parent[0] = 0
    parent_weight = [0] * n
    order = [0]
    for v in order:
        for u, w in graph[v]:
            if parent[u] == -1:
                parent[u] = v
                parent_weight[u] = w
                order.append(u)

    heaps = [None] * n
    for v in reversed(order):
        child_heaps = [heaps[u] for u, _ in graph[v] if parent[u] == v]
        if child_heaps:
            h = max(child_heaps, key=len)
            for other in child_heaps:
                if other is not h:
                    for x in other:
                        heapq.heappush(h, x)
        else:
            h = []

        if v != 0:
            if h:
                largest_marginal = heapq.heappop(h)
                heapq.heappush(h, largest_marginal - parent_weight[v])
            else:
                heapq.heappush(h, -parent_weight[v])
        heaps[v] = h

    h = heaps[0]
    answers = []
    covered = 0
    while h:
        covered -= heapq.heappop(h)
        answers.append(2 * covered)

    total = 2 * sum(parent_weight)
    answers.extend([total] * (n - len(answers)))
    sys.stdout.write('\n'.join(map(str, answers)))

