class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)

        def occurrences(t):
            if not t:
                return list(range(n + 1))

            m = len(t)
            prefix = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = prefix[j - 1]
                if t[i] == t[j]:
                    j += 1
                prefix[i] = j

            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = prefix[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    result.append(i - m + 1)
                    j = prefix[j - 1]
            return result

        starts_a = occurrences(a)
        starts_b = occurrences(b)
        starts_c = occurrences(c)
        if not starts_a or not starts_b or not starts_c:
            return -1

        import bisect
        best = n + 1
        for start in starts_a:
            ib = bisect.bisect_left(starts_b, start + len(a))
            if ib == len(starts_b):
                continue
            start_b = starts_b[ib]
            ic = bisect.bisect_left(starts_c, start_b + len(b))
            if ic == len(starts_c):
                continue
            best = min(best, starts_c[ic] + len(c) - start)

        return -1 if best == n + 1 else best

