class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)

        def occurrences(t):
            if not t:
                return list(range(n + 1))
            out = []
            pos = s.find(t)
            while pos != -1:
                out.append(pos)
                pos = s.find(t, pos + 1)
            return out

        aa, bb, cc = occurrences(a), occurrences(b), occurrences(c)
        if not aa or not bb or not cc:
            return -1
        import bisect
        best = n + 1
        for x in aa:
            bi = bisect.bisect_left(bb, x + len(a))
            if bi == len(bb):
                continue
            y = bb[bi]
            ci = bisect.bisect_left(cc, y + len(b))
            if ci == len(cc):
                continue
            z = cc[ci]
            best = min(best, z + len(c) - x)
        return -1 if best == n + 1 else best

