from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)

        # Iterative postorder traversal, preserving increasing child order.
        order = []
        stack = [(0, False)]
        while stack:
            v, done = stack.pop()
            if done:
                order.append(v)
            else:
                stack.append((v, True))
                for u in reversed(children[v]):
                    stack.append((u, False))

        pos = [0] * n
        subtree_size = [1] * n
        for i, v in enumerate(order):
            pos[v] = i
        for v in order:
            if parent[v] != -1:
                subtree_size[parent[v]] += subtree_size[v]

        text = ''.join(s[v] for v in order)

        # Manacher radii: odd[i] includes the center; even[i] is centered
        # between i-1 and i.
        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - k >= 0 and i + k < n and text[i - k] == text[i + k]:
                k += 1
            odd[i] = k
            if i + k - 1 > right:
                left, right = i - k + 1, i + k - 1

        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - k - 1 >= 0 and i + k < n and text[i - k - 1] == text[i + k]:
                k += 1
            even[i] = k
            if i + k - 1 > right:
                left, right = i - k, i + k - 1

        answer = [False] * n
        for v in range(n):
            end = pos[v]
            start = end - subtree_size[v] + 1
            length = subtree_size[v]
            if length % 2:
                center = (start + end) // 2
                answer[v] = odd[center] >= length // 2 + 1
            else:
                center = (start + end + 1) // 2
                answer[v] = even[center] >= length // 2
        return answer

