class Solution:
    def countPairs(self, nums: List[int]) -> int:
        def outcomes(x: int) -> set[int]:
            digits = list(str(x))
            result = {x}
            for i in range(len(digits)):
                for j in range(i + 1, len(digits)):
                    digits[i], digits[j] = digits[j], digits[i]
                    result.add(int(''.join(digits)))
                    digits[i], digits[j] = digits[j], digits[i]
            return result

        possible = [outcomes(x) for x in nums]
        answer = 0
        for i in range(len(nums)):
            for j in range(i):
                if nums[j] in possible[i] or nums[i] in possible[j]:
                    answer += 1
