class Solution:
    def minOperations(self, n: int, m: int) -> int:
        import heapq

        limit = 10000
        is_prime = [True] * limit
        is_prime[0] = is_prime[1] = False
        for p in range(2, 101):
            if is_prime[p]:
                for multiple in range(p * p, limit, p):
                    is_prime[multiple] = False

        if is_prime[n] or is_prime[m]:
            return -1

        inf = 10**30
        dist = [inf] * limit
        dist[n] = n  # Include the initial value in the total cost.
        heap = [(n, n)]

        while heap:
            cost, value = heapq.heappop(heap)
            if cost != dist[value]:
                continue
            if value == m:
                return cost

            digits = str(value)
            for i, char in enumerate(digits):
                digit = ord(char) - ord('0')
                for changed in (digit - 1, digit + 1):
                    if 0 <= changed <= 9:
                        neighbor = int(digits[:i] + str(changed) + digits[i + 1:])
                        if not is_prime[neighbor] and cost + neighbor < dist[neighbor]:
                            dist[neighbor] = cost + neighbor
                            heapq.heappush(heap, (dist[neighbor], neighbor))

        return -1

