class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n=len(nums)
        def z_array(start):
            m=n-start
            z=[0]*m
            l=r=0
            for k in range(1,m):
                if k<r:
                    z[k]=min(r-k,z[k-l])
                while k+z[k]<m and nums[start+z[k]]==nums[start+k+z[k]]:
                    z[k]+=1
                if k+z[k]>r:
                    l,r=k,k+z[k]
            return z
        z0=z_array(0)
        ans=0
        for i in range(1,n-1):
            m=n-i
            z=z_array(i)
            limit=m//2
            b=0
            overlap=0
            for k in range(1,limit+1):
                if z[k]>=k:
                    b+=1
                    if k>=i:
                        overlap+=1
            if z0[i]>=i:
                ans += max(0,n-2*i)+b-overlap
            else:
                ans += b
        return ans

