from typing import List

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Traverse reversed edges from 0: this finds nodes that can reach 0.
        reverse = [[] for _ in range(n)]
        weights = set()
        for a, b, w in edges:
            reverse[b].append((a, w))
            weights.add(w)

        candidates = sorted(weights)

        def feasible(limit: int) -> bool:
            seen = [False] * n
            seen[0] = True
            stack = [0]
            reached = 1
            while stack:
                v = stack.pop()
                for u, w in reverse[v]:
                    if w <= limit and not seen[u]:
                        seen[u] = True
                        reached += 1
                        stack.append(u)
            return reached == n

        if not feasible(candidates[-1]):
            return -1

        lo, hi = 0, len(candidates) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(candidates[mid]):
                hi = mid
            else:
                lo = mid + 1
        return candidates[lo]

