def sol(n, edges):
    rev=[[] for _ in range(n)]
    for a,b,w in edges: rev[b].append((a,w))
    d=[10**9]*n; d[0]=0; q=[(0,0)]
    while q:
        x,v=heapq.heappop(q)
        if x!=d[v]: continue
        for u,w in rev[v]:
            z=max(x,w)
            if z<d[u]: d[u]=z; heapq.heappush(q,(z,u))
    return -1 if max(d)==10**9 else max(d)

def cand(n,edges):
    ws=sorted(set(w for a,b,w in edges))
    def ok(x):
        seen={0}; st=[0]
        rev=[[] for _ in range(n)]
        for a,b,w in edges:
            if w<=x: rev[b].append(a)
        while st:
            for u in rev[st.pop()]:
                if u not in seen: seen.add(u); st.append(u)
        return len(seen)==n
    return next((w for w in ws if ok(w)),-1)
