class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        base = s.count('1')
        t = '1' + s + '1'

        runs = []
        i = 0
        while i < len(t):
            j = i + 1
            while j < len(t) and t[j] == t[i]:
                j += 1
            runs.append((t[i], j - i))
            i = j

        best_gain = 0
        for k in range(1, len(runs) - 1):
            if (runs[k][0] == '1' and runs[k - 1][0] == '0'
                    and runs[k + 1][0] == '0'):
                # Removing this interior 1-run merges its adjacent zero-runs;
                # flipping the merged run gains the sizes of those zero-runs.
                best_gain = max(best_gain, runs[k - 1][1] + runs[k + 1][1])

        return base + best_gain

